import React, { useState } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";

const Register = () => {
  const [name, setName] = useState("");
  const [morada, setMorada] = useState("");
  const [contacto, setContacto] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post("http://localhost:5000/alunos", {
        name,
        email,
        password,
        mor,
        password,
      });
      setMessage(response.data.message);
    } catch (error) {
      setMessage("Erro ao registrar. Tente novamente.");
    }
  };

  return (
    <div
      className="container-fluid d-flex justify-content-center align-items-center"
      style={{ backgroundColor: "#F8F9FA", minHeight: "100vh" }}
    >
      <div className="card p-4 shadow" style={{ width: "350px" }}>
        <h2 className="text-center">Registo</h2>
        {message && <div className="alert alert-info">{message}</div>}
        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label">Nome</label>
            <input
              type="text"
              className="form-control"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Digite seu nome"
              required
            />
            <div className="mb-3">
              <label className="form-label">Morada</label>
              <input
                type="text"
                className="form-control"
                value={morada}
                onChange={(e) => setMorada(e.target.value)}
                placeholder="Digite sua morada"
                required
              />
            </div>
            <div className="mb-3">
              <label className="form-label">Contacto</label>
              <input
                type="text"
                className="form-control"
                value={contacto}
                onChange={(e) => setContacto(e.target.value)}
                placeholder="Digite seu contacto"
                required
              />
            </div>
          </div>
          <div className="mb-3">
            <label className="form-label">Email</label>
            <input
              type="email"
              className="form-control"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Digite seu email"
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Senha</label>
            <input
              type="password"
              className="form-control"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Digite sua senha"
              required
            />
          </div>
          <button type="submit" className="btn btn-primary w-100">
            Registar
          </button>
        </form>
        <p className="text-center mt-3">
          Já tem uma conta? <a href="/login">Login</a>
        </p>
      </div>
    </div>
  );
};

export default Register;
